sp_widget.client_script:
api.controller=function() {
	/* widget controller */
	var c = this;
	$rootScope.$on('selectNoteEvent', function(event, data) {
		console.log('Listener caught NoteID: ' + data);
		/*
		c.server.get({
			action: 'getNote',
			noteID: data
		}).then(function(r){
			console.log(c.data);
			console.log(r.data);
			c.data.title = r.data.note.title;
			c.data.note = r.data.note.note;
			c.data.noteID = r.data.note.sys_id;
		})
		*/

		c.data.success = null;
		c.data.message = '';
		c.data.action = 'getNote';
		c.data.noteID = data;
		c.server.update().then(function(){
			console.log(c.data);
		})
	})

	c.editNote = function() {
		c.data.success = null;
		c.data.message = '';
	}

	c.updateNote = function() {
		c.data.action = 'updateNote';
		c.server.update().then(() => {
			$rootScope.$emit('updateNoteEvent', c.data.note.sys_id);
		})
	}

};

sp_widget.script:
(function() {
	/* populate the 'data' object */
	/* e.g., data.table = $sp.getValue('table'); */
	if (input && input.noteID) {
		var noteGr = new GlideRecord('x_snc_createnotes_note');
		if (noteGr.get(input.noteID)) {
			if (input.action == 'getNote') {
				data.note = {};
				$sp.getRecordDisplayValues(data.note, noteGr, "title, note, sys_id");
			}
			else if(input.action == 'updateNote') {
				console.log(data.note);
				console.log(input.note);
				noteGr.setValue('title', input.note.title);
				noteGr.setValue('note', input.note.note);
				try {
					noteGr.update();
					data.success = true;
					data.message = "Updated successfully";
				} catch (e) {
					data.success = false;
					data.message = "Failed to update: " + e.message;
				}
			}
		}
	}
})();
